import json, sys
from math_reward import compute_score
mismatch=0; n=0
for i in range(1,6):
    for line in open(f'outputs/grpo/rollouts/{i}.jsonl'):
        r=json.loads(line); n+=1
        got=compute_score(data_source='aime_like', solution_str=r['output'], ground_truth=r['gts'], extra_info=None)
